from prep import *
a=rd('source-onboarding-en.json');b=rd('source-onboarding-da.json')
for k,v in [('da',b),('en',a)]:
 c=rd('modern-'+k+'.json')['chapters'][0];v['openingChapterLabel']=c['title'];v['openingText']=c['paragraphs'][0]
a['about']=a['about'].replace("He gave Iago twice as many lines as Othello and let the audience watch the whole machinery from inside Iago's head while Othello, on stage, sees nothing.","Iago repeatedly confides in the audience. We hear him devise an accusation and then see Othello hear it as the reluctant testimony of a friend.").replace('There are no ghosts, no witches, no battle scenes after the opening — only two people in a bedroom, a handkerchief, and a man who has been talked into believing the worst.','Venice sends Othello to Cyprus to fight an invasion. A storm destroys the enemy fleet before the armies meet. The action moves from a public council chamber to a married couple’s bedroom.')
a['angleCards'][2]['text']=a['angleCards'][2]['text'].replace('dies asking forgiveness for her own murder','protects Othello with her final words when Emilia asks who killed her')
a['angleCards'][3]['text']="Before Othello arrives, Iago and Roderigo describe him to others through racial and sexual insults. In Act 3 Othello himself says, “I am black,” as he searches for a reason Desdemona might leave him. Compare that moment with the composed way he speaks before the Senate."
a['angleCards'][1]['text']=a['angleCards'][1]['text'].replace('at the start of Act 3','in Act 3, Scene 3')
a['cast'][0]['description']=a['cast'][0]['description'].replace('is the most decorated soldier in Venice','is the commander the Senate chooses to defend Cyprus')
a['cast'][1]['description']="Othello’s standard-bearer, passed over for the lieutenancy in favour of Cassio. He confides his schemes to the audience, so we can hear him invent a lie before we see another character believe it. Othello often calls him honest."
a['whyItMatters'][0]={'title':'How Iago Makes a Lie Believable','body':'When Cassio leaves Desdemona, Iago only has to say that he dislikes what he has seen. Othello starts asking questions for him. Later Iago lies outright, inventing a story about Cassio speaking of Desdemona in his sleep. He also plants a real handkerchief and arranges for Othello to hear Cassio laugh about Bianca without knowing which woman they mean. The audience can tell an outright lie from an ordinary gesture given a false meaning. Othello comes to treat them both as proof.'}
a['whyItMatters'][1]['body']=a['whyItMatters'][1]['body'].replace('Othello opens Act 3 happily married. By the end of Act 3 he is on his knees swearing to kill his wife.','Early in Act 3, Othello agrees to receive Cassio at Desdemona’s request. By the end of the garden scene he has knelt to swear revenge, ordered Cassio’s death and begun to plan Desdemona’s.')
a['whyItMatters'][2]={'title':'Who Gets to Describe Othello?','body':'Iago and Roderigo introduce Othello to the audience with animal comparisons and racial insults before he has a chance to speak. In the Senate, his account of his travels gives us a different measure of him. Desdemona explains what she heard in that story and why she chose him. The Duke supports the marriage but keeps the prejudice alive in a compliment that opposes fairness to blackness. Later Othello reaches for some of the same images as he struggles to explain his fear. In his last speech he asks the survivors to describe him as he is. By then the audience has heard how differently the same man can be described.'}
a['acclaim'][0].update(quote='The picturesque contrasts of character in this play are almost as remarkable as the depth of the passion.',context='Characters of Shakespear’s Plays, 1817')
a['acclaim'][1].update(quote='the motive-hunting of a motiveless malignity—how awful it is!',context='Note on Act I, scene III, The Literary Remains of Samuel Taylor Coleridge, vol. II')
b['estimatedTime']='Ca. 3 timer'
b['about']="""Othello er en maurisk general i Venedigs tjeneste. Han har i hemmelighed giftet sig med senatorsønnenes eftertragtede Desdemona, som selv har valgt ham. Hans fændrik Iago er blevet forbigået til en forfremmelse. Stillingen som løjtnant gik til Cassio. Nu vil Iago hævne sig. Han får Othello til at tro at Cassio og Desdemona er elskere. Et lommetørklæde han lægger på Cassios værelse, og en samtale som Othello kun hører en del af, bliver til beviser i generalens øjne. Othello kvæler Desdemona i deres seng. Først bagefter kommer løgnen for en dag. Så tager han sit eget liv.

Shakespeare skrev stykket omkring 1603 med udgangspunkt i en italiensk novelle af Cinthio. Iago betror sine planer til publikum. Vi hører ham opfinde en anklage og ser bagefter Othello høre den som modvilligt fremført sandhed fra en god ven. Men Othello får også selv ordet. Da han fortæller senatet hvordan Desdemona og han blev forelskede, lyder han helt anderledes end den mand Iago og Roderigo har beskrevet.

Venedig sender sin general til Cypern for at forsvare øen. En storm ødelægger den fjendtlige flåde før hærene mødes. Fra rådssalen og fæstningens vagtplads rykker tragedien stadig tættere på et privat rum. Til sidst afhænger et menneskes liv af hvad hendes mand tror er sket i deres seng."""
b['about']=b['about'].replace('senatorsønnenes eftertragtede Desdemona','senator Brabantios datter Desdemona')
cards=[
('Hvorfor hader Iago ham?','Iago vender tilbage til den forfremmelse han gik glip af, til rygtet om at Othello har været i seng med Emilia, og til sit had til maureren. Skifter grunden når han får en ny mulighed for at gøre skade?','Jeg vil følge de grunde Iago giver til sit had og se hvad der driver ham når ingen af dem slår til.'),
('Hvor hurtigt opstår mistanken?','I tredje akts havescene siger Iago et par ord da Cassio forlader Desdemona. Inden scenen er forbi, har Othello svoret hævn. Læg mærke til hvilket spørgsmål Othello selv stiller efter hver af Iagos pauser.','Jeg vil følge den samtale hvor Othello går fra at bede om bevis til selv at kræve Cassios død.'),
('Desdemonas valg','Desdemona vælger selv sin mand, forsvarer sit valg i senatet og følger ham til Cypern. Da hun ligger døende, vil hun stadig beskytte Othello. Hvad hører vi hende sige når mændene tier, og Emilia er hos hende?','Jeg vil følge Desdemona fra hendes første offentlige tale til hendes sidste ord til Emilia og se hvilke valg hun kan træffe undervejs.'),
('Hvem får lov at beskrive Othello?','Iago og Roderigo beskriver Othello med racistiske og seksuelle skældsord før han selv kommer på scenen. Senere overvejer han om hans hudfarve kan få Desdemona til at svigte ham. Lyt også til hvordan han taler om sig selv da han står for senatet.','Jeg vil skelne mellem andres billeder af Othello og hans eget sprog om sin hudfarve, sin tjeneste og sit ægteskab.')]
for v,t in zip(b['angleCards'],cards):v.update(dict(zip(('title','text','angleObjective'),t)))
cast=[
('Othello','Maurisk general','En sort general i Venedigs tjeneste, nygift med Desdemona. Senatet betror ham forsvaret af Cypern. Han er vant til at lede soldater og fortæller sin livshistorie uden at miste fatningen da han bliver anklaget for trolddom. Hjemme i ægteskabet får en betroet underordnet ham til at tvivle på den kvinde der selv valgte ham.'),
('Iago','Othellos fændrik','Han bærer Othellos fane og havde regnet med selv at blive løjtnant. Da Cassio får stillingen, tager han både generalen og løjtnanten under behandling. Han betror publikum sine planer, undertiden endnu mens han finder på dem. Othello kalder ham igen og igen hæderlig.'),
('Desdemona','Othellos kone','Senator Brabantios datter har giftet sig med Othello uden farens samtykke. Hun forklarer selv senatet hvorfor hun fulgte sin mand. På Cypern prøver hun at hjælpe Cassio tilbage til hans stilling. Iago forstår at få netop den hjælp til at se mistænkelig ud.'),
('Cassio','Othellos løjtnant','En uddannet ung officer fra Firenze som Othello foretrækker frem for Iago. Hans høflighed over for Desdemona og deres gamle bekendtskab giver Iago noget at bygge sine insinuationer på. Selv er han optaget af at genvinde sit embede og sit gode navn.'),
('Emilia','Iagos kone','Hun er Desdemonas kammerfrue. Da Desdemona taber sit lommetørklæde, samler Emilia det op og giver det til Iago uden at vide hvad han vil bruge det til. I den sidste scene gennemskuer hun hans rolle. Han befaler hende at tie. Hun fortæller hvad der skete.'),
('Roderigo','Iagos lettroende hjælper','En velhavende venetianer der vil have Desdemona. Han giver Iago penge og smykker i håb om at Iago hjælper ham med at vinde hende. Da Iago får brug for en mand med en kårde, overtaler han Roderigo til at angribe Cassio.')]
for v,t in zip(b['cast'],cast):v.update(dict(zip(('name','role','description'),t)))
b['acclaim'][0].update(quote='De levende kontraster mellem personerne i dette stykke er næsten lige så bemærkelsesværdige som lidenskabens dybde.',context=a['acclaim'][0]['context'])
b['acclaim'][1].update(quote='en ondskab uden motiv på jagt efter motiver – hvor er det uhyggeligt!',context='Note til første akt, tredje scene, The Literary Remains of Samuel Taylor Coleridge, bind II')
why=[
('Hvordan bliver en løgn troværdig?','Da Cassio går fra Desdemona, behøver Iago kun at sige at han ikke bryder sig om det han har set. Othello begynder selv at stille spørgsmål. Senere lyver Iago direkte og fortæller at Cassio har talt om Desdemona i søvne. Han lægger også et ægte lommetørklæde på Cassios værelse og lader Othello høre Cassio le ad Bianca uden at vide hvilken kvinde de taler om. Vi kan skelne den opdigtede historie fra den ægte latter som Iago giver en falsk betydning. For Othello bliver begge dele til beviser.'),
('En ed i slottets have','Tidligt i tredje akt lover Othello at tale med Cassio fordi Desdemona beder ham om det. Før havescenen er forbi, har han knælet og svoret hævn, befalet at Cassio skal dø og begyndt at planlægge Desdemonas død. Hvert skridt Iago tager, er lille. Han stiller et spørgsmål, tøver med at svare eller beder Othello glemme hvad han sagde. Othello går hver gang lidt længere. Først vil han se noget med egne øjne, senere er det nok at Iago siger han har set det.'),
('Hvem bestemmer hvad publikum ser?','Før Othello selv når at tale, har Iago og Roderigo sammenlignet ham med dyr og talt nedsættende om hans hudfarve. I senatet fortæller han om sine rejser med en ro som ikke ligner deres billede af ham. Desdemona fortæller hvad hun hørte i den historie. Selv dogens forsvar for ægteskabet fastholder modsætningen mellem det lyse og det sorte. Da mistanken får fat, griber Othello efter nogle af de samme billeder som de mænd der nedgjorde ham. I sin sidste tale beder han de overlevende beskrive ham som han er. Da har vi hørt hvor forskelligt den samme mand kan beskrives.')]
for v,t in zip(b['whyItMatters'],why):v.update(dict(zip(('title','body'),t)))
wr('onboarding-en.json',a);wr('onboarding-da.json',b)
